/* ===================== BÀI 19 · Vùng nhớ, con trỏ và tài nguyên ===================== */
/* Bài 19 · Vùng nhớ, con trỏ và tài nguyên (AMTS-EMB-001-M05-L03, MC51-019) — sinh bởi tools/author/mcu8051/l19.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P19=[{"label":"Ví dụ: data trực tiếp và idata gián tiếp","code":"; Ví dụ 1: a (data) ở 30H, b (idata) ở 90H.\n; Mã SDCC 4.2.0 sinh cho 01.c51: b luôn qua @R0.\n        ORG     0000H\n        MOV     30H,#55H                ; a = 0x55;  (trực tiếp)\n        MOV     R0,#90H                 ; b = 0xAA;  (gián tiếp:\n        MOV     @R0,#0AAH               ;   ô RAM cao 90H, không phải P1)\n        MOV     R0,#90H                 ; a = a + b;\n        MOV     A,@R0\n        ADD     A,30H\n        MOV     30H,A\n        SJMP    $                       ; while (1);\n        END\n","note":"a (data) ghi thẳng bằng địa chỉ 30H; b (idata ở 90H) phải qua R0. Đoán trước: sau MOV @R0,#0AAH, P1 có đổi không? (Không: @R0 với R0 = 90H ghi ô RAM cao, P1 vẫn FFH.) Cuối cùng a = 55H + AAH = FFH.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Mảng xdata qua DPTR và MOVX","code":"; Ví dụ 2: buf[4] xdata ở 0100H (RAM ngoài).\n; Mã SDCC 4.2.0 sinh cho 02.c51: mọi truy cập qua\n; DPTR và MOVX (2 chu kỳ máy mỗi lệnh MOVX).\n        ORG     0000H\n        MOV     DPTR,#0100H             ; buf[0] = 0x11;\n        MOV     A,#11H\n        MOVX    @DPTR,A\n        MOVX    A,@DPTR                 ; buf[3] = buf[0] + 1;\n        MOV     R7,A\n        INC     R7\n        MOV     DPTR,#0103H\n        MOV     A,R7\n        MOVX    @DPTR,A\n        SJMP    $                       ; while (1);\n        END\n","note":"Mỗi phần tử xdata cần nạp DPTR rồi MOVX (2 chu kỳ). Xem RAM ngoài ô 0100H và 0103H trong Bộ nhớ. SDCC thấy buf[0] vừa được ghi nên đọc lại ngay bằng MOVX A,@DPTR mà không nạp lại DPTR.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Bảng trong code và LED 7 đoạn","code":"; Ví dụ 3: bảng seg[10] trong bộ nhớ chương trình,\n; d ở 30H. Mã SDCC 4.2.0 sinh cho 03.c51.\n; LED 7 đoạn: đoạn ở P0, chọn chữ số bằng P2.0.\n        ORG     0000H\n        MOV     30H,#03H                ; d = 3;\n        MOV     P2,#0FEH                ; P2 = 0xFE;  chọn chữ số 1\n        MOV     A,30H                   ; P0 = seg[d];\n        MOV     DPTR,#SEG\n        MOVC    A,@A+DPTR               ;   đọc bảng trong CODE\n        MOV     P0,A\n        SJMP    $                       ; while (1);\nSEG:    DB      0C0H,0F9H,0A4H,0B0H,99H ; 0..4\n        DB      92H,82H,0F8H,80H,90H    ; 5..9\n        END\n","note":"Bảng nằm sau SJMP $, trong bộ nhớ chương trình (DB). MOVC A,@A+DPTR đọc byte ở SEG + 3 = B0H: mã của chữ số 3 (anode chung, đoạn sáng khi bit = 0). Đoán trước: A sau MOVC? (B0H.) LED 7 đoạn hiện số 3.","dev":{"seg":true},"fosc":12000000},{"label":"Ví dụ: Con trỏ xdata 2 byte","code":"; Ví dụ 4: buf[4] xdata ở 0200H, i ở 30H; con trỏ\n; px 2 byte giữ trong R7:R6, chép vào DPTR mỗi vòng.\n; Mã SDCC 4.2.0 sinh cho 04.c51.\n        ORG     0000H\n        MOV     30H,#00H                ; i = 0;\n        MOV     R6,#00H                 ; px = buf;  (byte thấp)\n        MOV     R7,#02H                 ;            (byte cao)\nVONG:   MOV     A,#0FCH                 ; i < 4 ?\n        ADD     A,30H\n        JC      XONG\n        MOV     R5,30H                  ; A = i + 0x41\n        MOV     A,#41H\n        ADD     A,R5\n        MOV     R5,A\n        MOV     DPL,R6                  ; *px = A;\n        MOV     DPH,R7\n        MOVX    @DPTR,A\n        INC     DPTR                    ; px++;\n        MOV     R6,DPL\n        MOV     R7,DPH\n        MOV     A,30H                   ; i++\n        INC     A\n        MOV     30H,A\n        SJMP    VONG\nXONG:   SJMP    $                       ; while (1);\n        END\n","note":"Con trỏ xdata px giữ trong R7:R6; mỗi vòng chép vào DPL/DPH, ghi, INC DPTR rồi chép ngược lại: 26 chu kỳ mỗi phần tử. Xem RAM ngoài 0200H–0203H thành 41H–44H ('A'–'D').","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Biến data ở 90H ghi vào P1","code":"; Ví dụ 5 (bẫy): unsigned char data c _at_ 0x90;\n; Địa chỉ trực tiếp 90H là SFR P1, không phải RAM.\n; Mã SDCC 4.2.0 sinh cho 05.c51: một lệnh, LED đổi.\n        ORG     0000H\n        MOV     90H,#0FH                ; c = 0x0F;  (ghi vào P1!)\n        SJMP    $                       ; while (1);\n        END\n","note":"Bẫy: biến data đặt ở 90H. Địa chỉ trực tiếp 90H là SFR P1, nên c = 0x0F thành MOV 90H,#0FH: LED P1.4–P1.7 sáng, ô RAM cao 90H vẫn 00H. SDCC không cảnh báo. Sửa: khai báo idata.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Con trỏ data đọc nhầm RAM trong","code":"; Ví dụ 6 (bẫy): buf xdata ở 0030H, x data ở 30H.\n; Con trỏ data chỉ đọc RAM trong (@R0), nên *p cho\n; 11H của x, không phải A5H của buf. Mã SDCC 4.2.0.\n        ORG     0000H\n        MOV     DPTR,#0030H             ; buf[0] = 0xA5;  RAM ngoài\n        MOV     A,#0A5H\n        MOVX    @DPTR,A\n        MOV     30H,#11H                ; x = 0x11;       RAM trong\n        MOV     R0,#30H                 ; p = (data *)0x30;\n        MOV     P1,@R0                  ; P1 = *p;  đọc RAM trong\n        SJMP    $                       ; while (1);\n        END\n","note":"Bẫy: buf (RAM ngoài 0030H) và x (RAM trong 30H) cùng con số. Con trỏ data dùng @R0 nên *p đọc 11H của x. Đoán trước: P1 cuối? (11H, không phải A5H.) Sửa: con trỏ xdata.","dev":{"led":true},"fosc":12000000}];
