makeQuiz("quiz19","score19",[{"q": "Biến unsigned char idata b _at_ 0x90; được ghi bằng lệnh nào?", "o": ["MOV R0,#90H rồi MOV @R0,#…", "MOV 90H,#…", "MOVX @DPTR,A với DPTR = 0090H", "MOVC A,@A+DPTR"], "a": 0, "e": "idata ở 80H–FFH chỉ đến được bằng địa chỉ gián tiếp @R0/@R1. MOV 90H,… là địa chỉ trực tiếp: ghi vào SFR P1."}, {"q": "Quên từ khóa code khi khai báo bảng 10 byte có giá trị đầu (SDCC, mô hình SMALL). Điều gì xảy ra?", "o": ["Không khác gì, trình biên dịch tự đưa vào ROM", "Lỗi dịch vì thiếu vùng nhớ", "Bảng chiếm 10 byte RAM trong và mã khởi động thêm lệnh chép giá trị đầu", "Bảng chuyển sang RAM ngoài"], "a": 2, "e": "Bảng thành biến RAM có giá trị đầu: SDCC xếp vào RAM trong (08H–11H trong lab) và sinh 10 lệnh MOV (30 byte) chạy trước main. Tổng ROM tăng từ 128 lên 147 byte."}, {"q": "Con trỏ chung unsigned char *p trên 8051 có kích thước bao nhiêu và vì sao chậm?", "o": ["2 byte; vì phải dùng DPTR", "1 byte; vì RAM trong chỉ 256 byte", "4 byte; vì địa chỉ 32 bit", "3 byte; mỗi lần *p phải gọi hàm thư viện xét byte vùng nhớ"], "a": 3, "e": "2 byte địa chỉ + 1 byte cho biết vùng (data, xdata, code…). Lệnh đọc phụ thuộc vùng nên phải xét lúc chạy: SDCC gọi __gptrget, 32 chu kỳ so với 14 khi dùng con trỏ data."}, {"q": "buf ở RAM ngoài 0030H, x ở RAM trong 30H. p = (unsigned char data *)0x30; thì *p đọc gì?", "o": ["buf[0] (RAM ngoài 0030H)", "x (RAM trong 30H)", "Byte ở địa chỉ 0030H của bộ nhớ chương trình", "Tùy giá trị trong thanh ghi B"], "a": 1, "e": "Con trỏ data chỉ sinh lệnh @R0/@R1 vào RAM trong; con số 30H không mang thông tin vùng nhớ. Muốn đọc buf phải dùng con trỏ xdata (MOVX)."}, {"q": "Dòng nào làm LED ở P1 đổi trạng thái?", "o": ["unsigned char data c _at_ 0x90; c = 0x0F;", "unsigned char idata c _at_ 0x90; c = 0x0F;", "unsigned char xdata c _at_ 0x0090; c = 0x0F;", "unsigned char code c[1] _at_ 0x0090 = {0x0F};"], "a": 0, "e": "Biến data dùng địa chỉ trực tiếp; trực tiếp 90H là SFR P1. idata ở 90H là ô RAM cao, xdata là RAM ngoài, code là ROM: không chạm P1."}]);

